-- 02-검증. 095000 적용 직후 (조회 전용). 모든 ok 가 true 여야 합니다.
SELECT no, item, actual, expected, actual IS NOT DISTINCT FROM expected AS ok
FROM (VALUES
    (1, '일지 정책 수(25개 테이블 × 1)', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[])), '25'),
    (2, '그중 로그인 사용자 전용 회사 범위 정책', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND policyname = tablename || '_org_access' AND roles::text = '{authenticated}' AND cmd = 'ALL'), '25'),
    (3, '기존 USING(true) 정책 남은 수', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND COALESCE(qual, 'true') = 'true'), '0'),
    (4, 'RLS 켜진 일지 테이블', (SELECT count(*)::text FROM pg_class WHERE oid = ANY (SELECT to_regclass('public.' || t) FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t) AND relrowsecurity), '25'),
    (5, 'anon 권한이 하나라도 남은 일지 테이블', (SELECT count(*)::text FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t WHERE has_table_privilege('anon', 'public.' || t, 'SELECT') OR has_table_privilege('anon', 'public.' || t, 'INSERT') OR has_table_privilege('anon', 'public.' || t, 'UPDATE') OR has_table_privilege('anon', 'public.' || t, 'DELETE')), '0'),
    (6, 'authenticated 조회·추가·수정·삭제 가능 테이블', (SELECT count(*)::text FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t WHERE has_table_privilege('authenticated', 'public.' || t, 'SELECT') AND has_table_privilege('authenticated', 'public.' || t, 'INSERT') AND has_table_privilege('authenticated', 'public.' || t, 'UPDATE') AND has_table_privilege('authenticated', 'public.' || t, 'DELETE')), '25'),
    (7, 'service_role(엑셀 내보내기 서버) RLS 우회', (SELECT rolbypassrls::text FROM pg_roles WHERE rolname = 'service_role'), 'true'),
    (8, 'daily_log_org_codes 함수 생성', (to_regprocedure('public.daily_log_org_codes()') IS NOT NULL)::text, 'true'),
    (9, 'daily_log_org_codes 실행 권한 anon', has_function_privilege('anon', 'public.daily_log_org_codes()', 'EXECUTE')::text, 'false'),
    (10, 'daily_log_org_codes 실행 권한 authenticated', has_function_privilege('authenticated', 'public.daily_log_org_codes()', 'EXECUTE')::text, 'true'),
    (11, 'daily_log_org_codes 소유자 권한 실행(SECURITY DEFINER)', (SELECT prosecdef::text FROM pg_proc WHERE oid = to_regprocedure('public.daily_log_org_codes()')), 'true'),
    (12, '로그인 없는 세션에서 함수 결과(빈 배열이어야 함)', (SELECT public.daily_log_org_codes()::text), '{}')
) AS v(no, item, actual, expected)
ORDER BY no;
